import{_ as e,o as i,c as t,a1 as s}from"./chunks/framework.CblolBb6.js";const u=JSON.parse('{"title":"Hari 2 - Peta 3D, Basis Data Spasial, dan GeoServer","description":"","frontmatter":{},"headers":[],"relativePath":"hari-2/index.md","filePath":"hari-2/index.md"}'),r={name:"hari-2/index.md"};function n(l,a,d,o,m,h){return i(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="hari-2-peta-3d-basis-data-spasial-dan-geoserver" tabindex="-1">Hari 2 - Peta 3D, Basis Data Spasial, dan GeoServer <a class="header-anchor" href="#hari-2-peta-3d-basis-data-spasial-dan-geoserver" aria-label="Permalink to &quot;Hari 2 - Peta 3D, Basis Data Spasial, dan GeoServer&quot;">​</a></h1><p>Hari kedua menyambungkan tiga hal yang sebelumnya berdiri sendiri: tampilan 3D di browser, tempat data disimpan, dan layanan yang menyajikan data itu. Sesi pagi membangun peta 3D dengan CesiumJS. Sesi siang membangun basis data spasial dan menghubungkannya ke GeoServer.</p><h2 id="jadwal-hari-2" tabindex="-1">Jadwal Hari 2 <a class="header-anchor" href="#jadwal-hari-2" aria-label="Permalink to &quot;Jadwal Hari 2&quot;">​</a></h2><p>Mengacu pada susunan acara pelatihan periode 15 sampai 18 September 2026.</p><table tabindex="0"><thead><tr><th>Waktu</th><th>Kegiatan</th><th>Materi di halaman ini</th></tr></thead><tbody><tr><td>08.00 - 10.00</td><td>Penjelasan CesiumJS, membuat tampilan 3D dan memuat layer 3D, kontrol kamera dan navigasi</td><td><a href="#peta-3d-dengan-cesiumjs">Peta 3D dengan CesiumJS</a></td></tr><tr><td>10.15 - 12.00</td><td>Database, tabel spasial dan non-spasial, relasi tabel, schema spasial, digitasi lewat database</td><td><a href="#basis-data-spasial">Basis Data Spasial</a></td></tr><tr><td>13.00 - 14.30</td><td>GeoServer workspace, store, layer dan style, store dari PostGIS, publish tabel dan menampilkan layer di Leaflet</td><td><a href="#geoserver">GeoServer</a></td></tr><tr><td>14.45 - 16.00</td><td>Penjelasan ORM Prisma, HTTP request, dan App Routes Next.js</td><td>Belum tersedia</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Tiga blok belum punya berkas materi</p><p>Penjelasan CesiumJS pembuka, materi tabel spasial dan non-spasial, serta penjelasan ORM Prisma dan App Routes belum punya halaman di repositori ini. Ketiganya saat ini disampaikan langsung oleh instruktur. Halaman ini akan diperbarui begitu materinya tersedia.</p></div><h2 id="peta-3d-dengan-cesiumjs" tabindex="-1">Peta 3D dengan CesiumJS <a class="header-anchor" href="#peta-3d-dengan-cesiumjs" aria-label="Permalink to &quot;Peta 3D dengan CesiumJS&quot;">​</a></h2><p>Enam praktik membangun peta 3D, dari viewer kosong sampai objek 3D yang bisa diklik.</p><ol><li><a href="/Pelatihan-WebGIS-BIG/hari-2/peta-3d-cesium/konfigurasi-viewer.html">Konfigurasi Cesium Viewer</a> - memuat library CesiumJS dan membuat viewer dengan basemap.</li><li><a href="/Pelatihan-WebGIS-BIG/hari-2/peta-3d-cesium/aset-3d-tiles.html">Impor dan Pengelolaan Aset 3D dan 3D Tiles</a> - mengunggah model 3D dan menampilkannya sebagai 3D Tiles.</li><li><a href="/Pelatihan-WebGIS-BIG/hari-2/peta-3d-cesium/terrain-citra.html">Terrain dan Citra: Integrasi Data Elevasi serta Drapping Citra Satelit</a> - mengaktifkan terrain dan menempelkan citra satelit di atasnya.</li><li><a href="/Pelatihan-WebGIS-BIG/hari-2/peta-3d-cesium/kontrol-kamera.html">Kontrol Kamera dan Navigasi</a> - mengatur posisi kamera dengan <code>flyTo</code> dan <code>setView</code>.</li><li><a href="/Pelatihan-WebGIS-BIG/hari-2/peta-3d-cesium/visualisasi-2d-3d.html">Visualisasi Data 2D dan 3D</a> - menampilkan data vektor 2D bersama objek 3D dalam satu tampilan.</li><li><a href="/Pelatihan-WebGIS-BIG/hari-2/peta-3d-cesium/interaksi-pengguna.html">Interaksi Pengguna</a> - menangani klik dan hover, lalu menampilkan informasi objek.</li></ol><h2 id="basis-data-spasial" tabindex="-1">Basis Data Spasial <a class="header-anchor" href="#basis-data-spasial" aria-label="Permalink to &quot;Basis Data Spasial&quot;">​</a></h2><ol><li><a href="/Pelatihan-WebGIS-BIG/hari-2/database-spasial/basis-data-lokal.html">Instalasi dan Konfigurasi Basis Data Local</a> - memasang PostgreSQL dan PostGIS di perangkat sendiri.</li><li><a href="/Pelatihan-WebGIS-BIG/hari-2/database-spasial/cloud-postgresql.html">Setup Cloud PostgreSQL + PostGIS + Koneksi Dbeaver</a> - menyiapkan basis data di Supabase dan menghubungkannya dari DBeaver maupun QGIS.</li></ol><h2 id="geoserver" tabindex="-1">GeoServer <a class="header-anchor" href="#geoserver" aria-label="Permalink to &quot;GeoServer&quot;">​</a></h2><ol><li><a href="/Pelatihan-WebGIS-BIG/hari-2/geoserver/instalasi-geoserver-vm.html">Instalasi GeoServer di VM</a> - menjalankan GeoServer di dalam VM memakai Docker.</li><li><a href="/Pelatihan-WebGIS-BIG/hari-2/geoserver/koneksi-postgis.html">Koneksi PostgreSQL ke GeoServer sebagai Data Store</a> - mendaftarkan basis data sebagai data store, mempublikasikan layer, dan mengatur style.</li></ol><h2 id="yang-perlu-disiapkan-peserta" tabindex="-1">Yang Perlu Disiapkan Peserta <a class="header-anchor" href="#yang-perlu-disiapkan-peserta" aria-label="Permalink to &quot;Yang Perlu Disiapkan Peserta&quot;">​</a></h2><ul><li>Token Cesium ion, dipakai pada <a href="/Pelatihan-WebGIS-BIG/hari-2/peta-3d-cesium/aset-3d-tiles.html">Impor dan Pengelolaan Aset 3D dan 3D Tiles</a>.</li><li>Akun Supabase untuk basis data cloud, dipakai pada <a href="/Pelatihan-WebGIS-BIG/hari-2/database-spasial/cloud-postgresql.html">Setup Cloud PostgreSQL + PostGIS + Koneksi Dbeaver</a>.</li><li>Virtual Machine dari Hari 3 bila GeoServer dijalankan di VM. Bila VM belum siap, GeoServer bisa dijalankan di perangkat sendiri lebih dahulu.</li></ul><h2 id="hasil-akhir-hari-2" tabindex="-1">Hasil Akhir Hari 2 <a class="header-anchor" href="#hasil-akhir-hari-2" aria-label="Permalink to &quot;Hasil Akhir Hari 2&quot;">​</a></h2><p>Di akhir hari, peserta memiliki basis data spasial berisi tabel PostGIS, satu instance GeoServer yang menyajikan layer dari basis data itu, dan halaman Next.js yang menampilkan globe 3D dengan terrain serta objek 3D yang dapat diklik.</p>',17)])])}const b=e(r,[["render",n]]);export{u as __pageData,b as default};
